# --- text as the emitter writes it -----------------------------------------------------------------------
# Every text of Ray is written `j"..."`: a string macro sees its text raw, so a `$` in it is only a `$`. The
# emitter escapes `\`, `"`, newlines and tabs; the raw reading has already undone the escapes before a quote
# (and at the end), and every other escape is undone here, once, when the file is read.
function unray(s::AbstractString)
  cs = collect(s)
  out = IOBuffer()
  i, n = 1, length(cs)
  while i <= n
    c = cs[i]
    if c != '\\'
      print(out, c); i += 1; continue
    end
    j = i
    while j <= n && cs[j] == '\\'; j += 1; end
    run = j - i
    if j > n || cs[j] == '"'
      for _ in 1:run; print(out, '\\'); end
      i = j; continue
    end
    for _ in 1:(run ÷ 2); print(out, '\\'); end
    if isodd(run)
      e = cs[j]
      if e == 'n'; print(out, '\n'); j += 1
      elseif e == 't'; print(out, '\t'); j += 1
      elseif e == 'r'; print(out, '\r'); j += 1
      elseif e == 'b'; print(out, '\b'); j += 1
      elseif e == 'f'; print(out, '\f'); j += 1
      elseif e == 'u' && j + 4 <= n; print(out, Char(parse(UInt32, String(cs[j+1:j+4]); base = 16))); j += 5
      else print(out, e); j += 1
      end
    end
    i = j
  end
  String(take!(out))
end
