# --- what every Ray object is ----------------------------------------------------------------------------
"""the root of every Ray class; the `{}` of Ray (`Node`) is the one that is only its slots"""
abstract type AbstractNode end
"""a field whose default has not been made yet (it is made on first read, as Ray makes it)"""
struct Unset end
const UNSET = Unset()
"""a new object, before its fields are set"""
struct Blank end
const BLANK = Blank()
const List = Base.Vector{Any}

"""`{}`: a map from names to values - Ray's dynamic members, and nothing else"""
mutable struct Node <: AbstractNode
  slots::Union{Nothing,Dict{Symbol,Any}}
end
function Node(; kw...)
  n = Node(Dict{Symbol,Any}())
  for (k, v) in kw; getfield(n, :slots)[k] = tonum(v); end
  n
end

"""a superposition: members apply elementwise, equal things collapse"""
struct Many
  items::List
end
Many(xs::AbstractVector) = Many(List(xs))

"""the module the classes are emitted into: where a member named at run time (`x[name]`) is found"""
const HOME = Ref{Module}(@__MODULE__)

# --- what `@class` records while the package is read, and what it registers when it runs ---------------------
const FIELDS = Dict{Symbol,Vector{Tuple{Symbol,Any,Bool}}}(:Node => Tuple{Symbol,Any,Bool}[])   # a class's fields, parents first
const CLASSNAMES = Set{Symbol}()                     # every Ray class read so far
const DECLARED = Set{Symbol}()                       # every member name that has its fallback
const STATICS = Dict{Tuple{Type,Symbol},Base.RefValue{Any}}()
const ZEROARG = Dict{Type,Set{Symbol}}()           # the members a class reads without arguments (fields, getters)
const THEORIES = Any[]

tonum(@nospecialize(x)) = x isa Bool ? x : x isa Real ? Float64(x) : x isa AbstractVector && !(x isa List) ? Any[tonum(y) for y in x] : x

"""a value into a field of this type: whole numbers are Float64, as every number of Ray is"""
fit(::Type{T}, @nospecialize(v)) where {T} = v isa Integer && !(v isa Bool) ? Float64(v) : v

"""`Class(x: 1, ...)`: positional values fill the fields in the order they are declared, named ones by name"""
function construct!(o::AbstractNode, names::Tuple, args::Tuple, kw)
  for (i, v) in enumerate(args)
    i <= length(names) || break
    setproperty!(o, names[i], v)
  end
  for (k, v) in kw
    setproperty!(o, k, v)
  end
  o
end

# a field typed as Ray types it: a number, a truth, a text or a list; any other value is Any
function fieldtype_of(t)
  base = t === :Float64 ? :Float64 : t === :Bool ? :Bool : t === :String ? :String : t === :List ? :($List) : nothing
  base === nothing ? :Any : :(Union{$Unset,Nothing,$base})
end
isstatic_sig(a) = a isa Expr && a.head === :(::) && length(a.args) == 2 && a.args[2] isa Expr && a.args[2].head === :curly && a.args[2].args[1] === :Type
function replace_sym(e, from::Symbol, to)
  e === from && return to
  e isa Expr || return e
  Expr(e.head, (replace_sym(a, from, to) for a in e.args)...)
end
defname(e) = e isa Expr && e.head === :function && e.args[1] isa Expr && e.args[1].head === :call ? e.args[1].args[1] : nothing
defargs(e) = e.args[1].args[2:end]
ismacro(e, m::Symbol) = e isa Expr && e.head === :macrocall && e.args[1] === m
macroargs(e) = filter(a -> !(a isa LineNumberNode), e.args[2:end])
function fallback(n::Symbol)
  x, a = gensym("x"), gensym("a")
